mapper.update:
UPDATE t_user
SET device_token = #{deviceToken}
WHERE id = #{id};

UPDATE t_user
SET device_token = null
WHERE device_token = #{deviceToken};

UPDATE t_user
SET device_token = null
WHERE id = #{userId};

UPDATE t_user
SET category = #{category, typeHandler=com.wannabe.app.main.utility.mybatis.StringListHandler},
    city     = #{city},
    district = #{district, typeHandler=com.wannabe.app.main.utility.mybatis.StringListHandler}
WHERE id = #{id};

